<template>
  <div class="page-container gpm-page">
    <div class="page-head"><div><h2>种植主体管理</h2><p>统一维护规模大户、家庭农场、合作社和农业企业等种植主体档案。</p></div><div class="page-actions"><el-button @click="exportSubjects">导出主体</el-button><el-button @click="triggerImport">导入主体</el-button><input ref="importInput" type="file" accept=".csv,text/csv" hidden @change="importSubjects"/><el-button type="primary" @click="openEdit()">新增主体</el-button></div></div>
    <div class="panel">
      <div class="panel-title"><span class="title-text">种植主体</span><span class="title-extra">共 {{ subjects.length }} 个</span></div>
      <el-form :inline="true" class="filters"><el-form-item label="关键字"><el-input v-model="subjectFilters.keyword" clearable placeholder="名称/负责人/编号" /></el-form-item><el-form-item label="类型"><el-select v-model="subjectFilters.type" clearable placeholder="全部" style="width:140px"><el-option label="合作社" value="cooperative"/><el-option label="家庭农场" value="family_farm"/><el-option label="农业企业" value="enterprise"/><el-option label="种植大户" value="big_household"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="subjectFilters.status" clearable placeholder="全部" style="width:110px"><el-option label="启用" value="启用"/><el-option label="停用" value="停用"/></el-select></el-form-item><el-form-item label="所在区域"><el-cascader v-model="subjectFilters.regionCode" :options="regionOptions" :props="regionProps" clearable filterable placeholder="安徽省内市/县/乡" style="width:240px"/></el-form-item><el-button type="primary" @click="loadSubjects">查询</el-button></el-form>
      <el-table :data="subjects" stripe height="360"><el-table-column prop="id" label="主体编号" width="120"/><el-table-column prop="name" label="主体名称" min-width="220" show-overflow-tooltip/><el-table-column prop="type" label="主体类型" width="110"><template #default="{row}">{{ typeName(row.type) }}</template></el-table-column><el-table-column prop="owner" label="负责人" width="100"/><el-table-column prop="phone" label="联系手机" width="130"/><el-table-column prop="primaryCrop" label="主要作物" width="100"/><el-table-column prop="regionName" label="所属行政区划" min-width="180" show-overflow-tooltip/><el-table-column prop="area" label="种植规模(亩)" width="120"/><el-table-column prop="muInvestment" label="亩投入(元)" width="110" align="right"/><el-table-column prop="muNetIncome" label="亩纯收益(元)" width="120" align="right"/><el-table-column label="历史填报" width="100"><template #default="{row}"><el-button link type="primary" @click="showHistory(row)">查看记录</el-button></template></el-table-column><el-table-column label="启用状态" width="85"><template #default="{row}"><el-tag size="small" :type="row.status === '启用' ? 'success' : 'info'">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="关联地块" width="90"><template #default="{row}"><el-button link type="primary" @click="openPlots(row)">{{ row.plotCount || 0 }}</el-button></template></el-table-column><el-table-column label="操作" width="260" fixed="right"><template #default="{row}"><el-button v-if="userStore.role?.code === 'province' && row.auditStatus === '待省级审核'" link type="success" @click="auditSubject(row, '已审核')">通过</el-button><el-button v-if="userStore.role?.code === 'province' && row.auditStatus === '待省级审核'" link type="danger" @click="auditSubject(row, '已退回')">退回</el-button><el-button link type="primary" @click="openEdit(row)" :disabled="!canManageSubject(row)">编辑</el-button><el-button link :type="row.status === '启用' ? 'warning' : 'success'" @click="toggleStatus(row)" :disabled="!canManageSubject(row)">{{ row.status === '启用' ? '停用' : '启用' }}</el-button><el-button link type="primary" @click="openPlots(row)">关联地块</el-button><el-button link type="danger" @click="removeSubject(row)" :disabled="!canManageSubject(row)">删除</el-button></template></el-table-column></el-table>
    </div>

    <el-dialog v-model="editVisible" :title="form.id ? '编辑种植主体' : '新增种植主体'" width="680px"><el-form :model="form" label-width="100px"><el-row :gutter="16"><el-col :span="12"><el-form-item label="主体名称" required><el-input v-model="form.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="主体类型" required><el-select v-model="form.type" style="width:100%"><el-option label="合作社" value="cooperative"/><el-option label="家庭农场" value="family_farm"/><el-option label="农业企业" value="enterprise"/><el-option label="种植大户" value="big_household"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="负责人" required><el-input v-model="form.owner"/></el-form-item></el-col><el-col :span="12"><el-form-item label="联系手机" required><el-input v-model="form.phone" maxlength="11" placeholder="请输入11位手机号码"/></el-form-item></el-col><el-col :span="12"><el-form-item label="主要作物" required><el-select v-model="form.primaryCrop" style="width:100%"><el-option label="小麦" value="小麦"/><el-option label="水稻" value="水稻"/><el-option label="玉米" value="玉米"/><el-option label="大豆" value="大豆"/><el-option label="其他" value="其他"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="所属行政区划" required><el-cascader v-model="form.regionCode" :options="regionOptions" :props="regionProps" clearable filterable placeholder="选择市/县/乡" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="种植规模"><el-input-number v-model="form.area" :min="0" :precision="1" style="width:100%"/><span class="unit-tip">亩</span></el-form-item></el-col><el-col :span="12"><el-form-item label="亩投入"><el-input-number v-model="form.muInvestment" :min="0" :precision="2" style="width:100%"/><span class="unit-tip">元/亩</span></el-form-item></el-col><el-col :span="12"><el-form-item label="亩纯收益"><el-input-number v-model="form.muNetIncome" :min="0" :precision="2" style="width:100%"/><span class="unit-tip">元/亩</span></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="editVisible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
    <el-dialog v-model="historyVisible" :title="`历史填报记录：${currentSubject?.name || ''}`" width="900px"><el-table :data="historyRows" border stripe max-height="420"><el-table-column prop="date" label="填报日期" width="120"/><el-table-column prop="planName" label="关联计划" min-width="220" show-overflow-tooltip/><el-table-column prop="plotId" label="地块编号" min-width="150"/><el-table-column prop="cropName" label="作物" width="100"/><el-table-column label="填报类型" width="100"><template #default="{row}">{{ progressTypeName(row.type) }}</template></el-table-column><el-table-column prop="area" label="填报面积(亩)" width="130"/><el-table-column prop="source" label="填报来源" min-width="130"/></el-table><el-empty v-if="!historyRows.length" description="暂无历史填报记录"/><template #footer><el-button type="primary" @click="historyVisible=false">关闭</el-button></template></el-dialog>
    <el-dialog v-model="plotVisible" :title="`关联地块：${currentSubject?.name || ''}`" width="1050px"><el-tabs v-model="plotTab"><el-tab-pane label="已关联地块" name="linked"><el-form :inline="true" class="plot-filters"><el-form-item label="关键字"><el-input v-model="linkedFilters.keyword" clearable placeholder="地块名称/编号"/></el-form-item><el-form-item label="所属行政区划"><el-cascader v-model="linkedFilters.regionCode" :options="regionOptions" :props="regionProps" clearable filterable placeholder="选择市/县/乡" style="width:230px"/></el-form-item><el-button type="primary" @click="loadLinkedPlots">查询</el-button></el-form><el-table :data="linkedPlots" border stripe height="320"><el-table-column prop="plotId" label="地块编号" width="130"/><el-table-column prop="plotName" label="地块名称" min-width="220"/><el-table-column prop="area" label="面积(亩)" width="110"/><el-table-column prop="crop" label="种植作物" width="110"/><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="danger" @click="unbindPlot(row)">解除关联</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="选择地块关联" name="available"><el-form :inline="true" class="plot-filters"><el-form-item label="关键字"><el-input v-model="availableFilters.keyword" clearable placeholder="地块名称/编号"/></el-form-item><el-form-item label="来源"><el-select v-model="availableFilters.source" clearable placeholder="全部" style="width:130px"><el-option label="确权地块" value="确权"/><el-option label="流转地块" value="流转"/></el-select></el-form-item><el-form-item label="所属行政区划"><el-cascader v-model="availableFilters.regionCode" :options="regionOptions" :props="regionProps" clearable filterable placeholder="选择市/县/乡" style="width:230px"/></el-form-item><el-button type="primary" @click="loadAvailablePlots">查询</el-button></el-form><el-table ref="availableTable" :data="availablePlots" border stripe height="320" @selection-change="selectedPlots = $event"><el-table-column type="selection" width="55"/><el-table-column prop="id" label="地块编号" width="130"/><el-table-column prop="name" label="地块名称" min-width="220"/><el-table-column prop="area" label="面积(亩)" width="110"/><el-table-column prop="cropName" label="种植作物" width="110"/><el-table-column prop="unitName" label="所属单位" min-width="160"/></el-table><div class="selected-tip">已选择 {{ selectedPlots.length }} 个地块</div></el-tab-pane></el-tabs><template #footer><el-button @click="plotVisible=false">关闭</el-button><el-button v-if="plotTab === 'available'" type="primary" @click="bindPlots">确认关联</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { auditPlanSubject, bindSubjectPlots, deletePlanSubject, fetchAvailablePlanPlots, fetchPlanSubjects, fetchProgressRecords, fetchSubjectPlotRelations, savePlanSubject, setPlanSubjectStatus, unbindSubjectPlotRelation } from '@/api/gpm'
import { getRegion, REGION_TREE } from '@/mock/common/regions'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const subjects = ref([]); const editVisible = ref(false); const importInput = ref(null); const historyVisible = ref(false); const historyRows = ref([]); const plotVisible = ref(false); const plotTab = ref('linked'); const currentSubject = ref(null); const linkedPlots = ref([]); const availablePlots = ref([]); const selectedPlots = ref([]); const subjectFilters = reactive({ keyword: '', type: '', status: '', regionCode: '' }); const linkedFilters = reactive({ keyword: '', regionCode: '' }); const availableFilters = reactive({ keyword: '', source: '', regionCode: '' }); const regionProps = { value: 'code', label: 'name', children: 'children', emitPath: false }; const regionOptions = REGION_TREE[0]?.children || []; const emptyForm = () => ({ id: '', name: '', type: 'cooperative', owner: '', phone: '', primaryCrop: '小麦', regionCode: userStore.role?.regionCode || '', regionName: '', area: 0, muInvestment: 0, muNetIncome: 0, status: '启用' }); const form = reactive(emptyForm())
const typeName = type => ({ cooperative: '合作社', family_farm: '家庭农场', enterprise: '农业企业', big_household: '种植大户' }[type] || type)
const progressTypeName = type => ({ planting: '种植', sow: '播种', harvest: '收获' }[type] || type)
const typeValue = type => ({ 合作社: 'cooperative', 家庭农场: 'family_farm', 农业企业: 'enterprise', 种植大户: 'big_household' }[type] || type)
const loadSubjects = async () => { subjects.value = await fetchPlanSubjects(userStore.role, subjectFilters) }; const canManageSubject = row => !row || userStore.role?.code === 'province' || (row.regionCode && String(row.regionCode).startsWith(String(userStore.role?.regionCode || ''))); const showHistory = async row => { currentSubject.value = row; historyRows.value = (await fetchProgressRecords(userStore.role)).filter(item => item.subjectId === row.id); historyVisible.value = true }; const openEdit = row => { Object.assign(form, emptyForm(), row || {}); editVisible.value = true }; const save = async () => { if (!form.name || !form.owner || !form.regionCode || !form.primaryCrop || !form.phone) return ElMessage.warning('请完整填写主体名称、负责人、所属行政区划、主要作物和联系手机'); if (!/^1\d{10}$/.test(form.phone) && !/^1\d{2}\*{4}\d{4}$/.test(form.phone)) return ElMessage.warning('请输入正确的11位联系手机'); const regionCode = Array.isArray(form.regionCode) ? form.regionCode.at(-1) : form.regionCode; const regionName = getRegion(regionCode)?.path || form.regionName; const result = await savePlanSubject({ ...form, regionCode, regionName }, userStore.role); if (!result.success) return ElMessage.error(result.message); ElMessage.success('主体档案已保存'); editVisible.value = false; await loadSubjects() }; const toggleStatus = async row => { const nextStatus = row.status === '启用' ? '停用' : '启用'; try { await ElMessageBox.confirm(`确认${nextStatus}主体“${row.name}”？`, '状态变更确认', { type: 'warning', confirmButtonText: '确认', cancelButtonText: '取消' }) } catch { return } const result = await setPlanSubjectStatus(row.id, nextStatus, userStore.role || {}); if (!result.success) return ElMessage.error(result.message); ElMessage.success(`主体已${nextStatus}`); await loadSubjects() }; const loadLinkedPlots = async () => { if (!currentSubject.value) return; linkedPlots.value = await fetchSubjectPlotRelations(userStore.role, { subjectId: currentSubject.value.id, keyword: linkedFilters.keyword, regionCode: linkedFilters.regionCode, status: '已关联' }) }; const loadAvailablePlots = async () => { availablePlots.value = await fetchAvailablePlanPlots(userStore.role, availableFilters) }; const openPlots = async row => { currentSubject.value = row; plotTab.value = 'linked'; linkedFilters.keyword = ''; availableFilters.keyword = ''; availableFilters.source = ''; availableFilters.regionCode = ''; linkedFilters.regionCode = ''; selectedPlots.value = []; plotVisible.value = true; await Promise.all([loadLinkedPlots(), loadAvailablePlots()]) }; const bindPlots = async () => { if (!currentSubject.value) return; if (!selectedPlots.value.length) return ElMessage.warning('请至少选择一个地块'); const result = await bindSubjectPlots(currentSubject.value.id, selectedPlots.value.map(item => item.id), userStore.role); if (!result.success) return ElMessage.error(result.message); ElMessage.success(`已关联${result.count}个地块`); selectedPlots.value = []; await loadSubjects(); await loadLinkedPlots(); await loadAvailablePlots(); plotTab.value = 'linked' }; const unbindPlot = async row => { try { await ElMessageBox.confirm(`确认解除地块“${row.plotName}”与当前主体的关联吗？`, '解除关联确认', { type: 'warning', confirmButtonText: '确认解除', cancelButtonText: '取消' }) } catch { return } const result = await unbindSubjectPlotRelation(row.id, { reason: '主体管理页面解除关联', operator: userStore.role?.name || userStore.regionName }); if (!result.success) return ElMessage.error(result.message); ElMessage.success('地块已解除关联'); await loadSubjects(); await loadLinkedPlots(); await loadAvailablePlots() };
const auditSubject = async (row, status) => { const opinion = status === '已退回' ? '请补充主体档案信息后重新提交' : ''; const result = await auditPlanSubject(row.id, status, opinion, userStore.role); if (!result.success) return ElMessage.error(result.message); ElMessage.success(status === '已审核' ? '主体审核已通过' : '主体已退回修改'); await loadSubjects() }
const removeSubject = async row => { try { await ElMessageBox.confirm(`确认删除种植主体“${row.name}”？删除后无法恢复。`, '删除确认', { type: 'warning', confirmButtonText: '确认删除', cancelButtonText: '取消' }) } catch { return } const result = await deletePlanSubject(row.id, userStore.role); if (!result.success) return ElMessage.error(result.message); ElMessage.success('种植主体已删除'); await loadSubjects() }
const csvFields = [['id', '主体编号'], ['name', '主体名称'], ['type', '主体类型'], ['owner', '负责人'], ['phone', '联系手机'], ['primaryCrop', '主要作物'], ['regionName', '所属行政区划'], ['regionCode', '行政区划编码'], ['area', '种植规模(亩)'], ['muInvestment', '亩投入(元)'], ['muNetIncome', '亩纯收益(元)']]
const csvEscape = value => { const text = String(value ?? ''); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text }
const exportSubjects = () => { const csv = '\ufeff' + csvFields.map(([, label]) => label).join(',') + '\n' + subjects.value.map(row => csvFields.map(([field]) => csvEscape(row[field])).join(',')).join('\n'); const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `种植主体_${new Date().toISOString().slice(0, 10)}.csv`; link.click(); URL.revokeObjectURL(url); ElMessage.success('种植主体数据已导出') }
const triggerImport = () => { importInput.value?.click() }
const parseCsv = text => { const rows = []; let row = []; let cell = ''; let quoted = false; for (let i = 0; i < text.length; i += 1) { const char = text[i]; const next = text[i + 1]; if (char === '"' && quoted && next === '"') { cell += '"'; i += 1 } else if (char === '"') quoted = !quoted; else if (char === ',' && !quoted) { row.push(cell); cell = '' } else if ((char === '\n' || char === '\r') && !quoted) { if (char === '\r' && next === '\n') i += 1; row.push(cell); if (row.some(value => value.trim())) rows.push(row); row = []; cell = '' } else cell += char } if (cell || row.length) { row.push(cell); if (row.some(value => value.trim())) rows.push(row) } return rows }
const importSubjects = event => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = async () => { const rows = parseCsv(String(reader.result || '').replace(/^\ufeff/, '')); const headers = rows.shift() || []; const index = Object.fromEntries(csvFields.map(([field, label]) => [label, headers.indexOf(label)])); const imported = rows.map(row => ({ ...Object.fromEntries(csvFields.map(([field, label]) => [field, row[index[label]] ?? ''])), type: typeValue(row[index['主体类型']] || '') })); let successCount = 0; for (const item of imported) { const result = await savePlanSubject({ ...emptyForm(), ...item, area: Number(item.area || 0), muInvestment: Number(item.muInvestment || 0), muNetIncome: Number(item.muNetIncome || 0) }, userStore.role); if (result.success) successCount += 1 } await loadSubjects(); if (successCount === imported.length) ElMessage.success(`成功导入${successCount}条种植主体`); else ElMessage.warning(`已导入${successCount}条，${imported.length - successCount}条校验未通过`); event.target.value = '' }; reader.readAsText(file, 'UTF-8') }
onMounted(loadSubjects)
</script>
<style lang="scss" scoped>.gpm-page{gap:12px;overflow:auto}.page-head{display:flex;justify-content:space-between;align-items:flex-start}.page-actions{display:flex;gap:8px;align-items:center}.eyebrow{color:var(--ah-primary);font-size:11px;letter-spacing:1px;font-weight:700}h2{margin:4px 0;color:var(--ah-text);font-size:22px}.page-head p{color:var(--ah-text-secondary);font-size:13px}.filters{display:flex;align-items:center;flex-wrap:wrap}.filters :deep(.el-form-item){margin-bottom:12px;margin-right:12px}.relation-panel{min-height:400px}.plot-filters{display:flex;align-items:center;flex-wrap:nowrap;white-space:nowrap;gap:0}.plot-filters :deep(.el-form-item){margin-right:12px;margin-bottom:12px;flex-shrink:0}.plot-filters :deep(.el-button){flex-shrink:0;margin-bottom:12px}.selected-tip{margin-top:10px;color:var(--ah-text-secondary);font-size:12px}.unit-tip{margin-left:8px;color:var(--ah-text-secondary);font-size:12px;white-space:nowrap}</style>
